style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com") {
html, body {
    background: url("https://instasize.com/p/2fb2b74bd8d903b8d200f6a0e17671568831e4bf366cd51d7a56a2ae62257d96") 
                no-repeat center center fixed !important;
    background-size: cover !important;
    background-color: black !important;
    color: #fff !important;
  }

  /* Eliminar fondos blancos de TODOS los divs y secciones */
  div, section, article, main, aside {
    background: transparent !important;
    background-image: none !important;
  }

  /* Barra superior y menú lateral */
  header, nav, .navbar, .menu, .sidebar {
    background: rgba(0,0,0,0.6) !important;  /* semitransparente para que no desaparezcan */
  }

  /* Botones e inputs que sí necesitan fondo */
  button, input, textarea, select {
    background-color: #1c1c1c !important;
    color: #ffffff !important;
    border: 1px solid #333 !important;
  }

  /* Mantener el texto blanco para que se lea */
  h1, h2, h3, h4, h5, h6, p, span, a, label, strong {
    color: #ffffff !important;
  }
}
